reducedMotion.body:
@media (prefers-reduced-motion: reduce) {
  .orbit, .aura, .drift, .scan { animation: auto ease 0s 1 normal none running none; }
  .card, .card-img, .step, .btn-p, .btn-g, .slot { transition: none; }
}

@media (prefers-reduced-motion: reduce) {
  .plate { animation: auto ease 0s 1 normal none running none; }
  .st-in, .st-ic, .btn-p, .btn-g { transition: none; }
}

@media (prefers-reduced-motion: reduce) {
  .who-in, .flag, .btn-p { transition: none; }
  .pin::before { animation: auto ease 0s 1 normal none running none; }
}
